"""
Étend les messages avec les namespaces Comparer, ComparerTrajet, Simulateur
pour les 6 locales. Écriture atomique tempfile + os.replace.
"""
import json
import os
import tempfile


def atomic_write(target: str, content: str) -> str:
    target_dir = os.path.dirname(target) or "."
    fd, tmp = tempfile.mkstemp(prefix=".atomic_", dir=target_dir)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write(content)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, target)
    except Exception:
        try:
            os.unlink(tmp)
        except FileNotFoundError:
            pass
        raise
    data = open(target, "rb").read()
    return "size=" + str(len(data)) + " nulls=" + str(b"\x00" in data)


