# =========================================================================
# WRITE
# =========================================================================
for locale in ("fr", "en", "nl", "de", "es", "it"):
    path = f"messages/{locale}.json"
    with open(path, "r", encoding="utf-8") as f:
        msgs = json.load(f)
    msgs["Comparer"] = COMPARER[locale]
    msgs["ComparerTrajet"] = COMPARER_TRAJET[locale]
    msgs["Simulateur"] = SIMULATEUR[locale]
    content = json.dumps(msgs, ensure_ascii=False, indent=2) + "\n"
    print(f"{locale}: {atomic_write(path, content)}")
